\begin{lemma}[A weak minimum below the filling-area infimum]
\label{lem:annular-disk-minimum}
\uses{lem:annular-weak-disks,lem:annular-energy-competitor}
\lean{PoincareMT.m65Plateau_weak_minimum}
Under the hypotheses of Theorem~\ref{thm:annular-plateau}, the
normalized weak spanning-disk class has an energy minimum $u$,
and $E(u)\leq A_g(\gamma)$.
\end{lemma}
\begin{proof}
The supplied filling disk makes the class nonempty.
Lemma~\ref{lem:annular-weak-disks} gives a minimum.
Apply Lemma~\ref{lem:annular-energy-competitor} to each actual
spanning disk and then let its positive error tend to zero.
Taking the guarded area infimum proves the inequality.
\end{proof}

